    summary = {"passed": 0, "failed": 0, "skipped": 0}
    for result in results:
        if result["status"] == "passed":
            summary["passed"] += 1
        elif result["status"] == "failed":
            summary["failed"] += 1
        elif result["status"] == "skipped":
            summary["skipped"] += 1
        else:
